Definition MVA      : Z := 0x69254.
Definition LOOP_PC  : Z := 0x69280.
Definition DRET1    : Z := 0x69294.
Definition L2_PC    : Z := 0x6929c.
Definition ZL_PC    : Z := 0x692c0.
Definition ZEND     : Z := 0x692e0.
Definition L1_PC    : Z := 0x692e4.
Definition DRET2    : Z := 0x69304.
Definition FLW_PC   : Z := 0x6930c.
Definition FSW_PC   : Z := 0x69324.
Definition AFTER_FSW : Z := 0x69328.
Definition END_PC   : Z := 0x693a8.
Definition RET_PC   : Z := 0x693bc.
Definition TRAP_PC  : Z := 0x693c0.
Definition DELSZ    : Z := 0x6f8cc.
Definition DELETE   : Z := 0x6f8c8.

Definition STOPS : list Z := [LOOP_PC; L2_PC; ZL_PC; ZEND; DELSZ; FLW_PC; FSW_PC; END_PC; RET_PC; TRAP_PC].

Section MvaU1.
Context {AC : AllocCeiling}.
  Variable L : Layout.
  Variable MI : MallocIface SEGS L.
  Variable ST : StaticsIface SEGS L.
  Variable DEL_STACK : Z.
  Hypothesis DEL_STACK_nn : 0 <= DEL_STACK.
  Hypothesis DEL : delete_rule_stmt SEGS L MI DEL_STACK.

  Hypothesis HLdel : ly_delete L = DELETE.
  Hypothesis HLimg_lo : forall a, in_ranges (ly_img L) a -> a < alloc_ceiling.
  Hypothesis HLrw_img : forall a, in_ranges (ly_rw L) a -> in_ranges (ly_img L) a.
  Hypothesis HLrelro_img : forall a, in_ranges (ly_relro L) a -> in_ranges (ly_img L) a.
  Hypothesis HLrw_relro : forall a, in_ranges (ly_rw L) a -> ~ in_ranges (ly_relro L) a.
  Hypothesis HLerr_rw : forall a, errno_win L a -> in_ranges (ly_rw L) a.

  Variables (NS : Z) (V : Type) (nval : mem -> Z -> V -> Prop).
  Hypothesis HNS : 24 <= NS.
  Hypothesis nval_agree : forall M M' p v, nval M p v -> agree_on M M' (p + 20) (NS - 20) -> 0 < p -> p + NS <= 2 ^ 47 -> nval M' p v.

  #[local] Abbreviation cfg fx R pc M model := (mkCfg (@mkst fx R (Z_to_bv 64 pc) M (seg_rom SEGS)) model).

  Lemma live_facts : forall A M model p n, ainv MI A M model -> In (p, n) (live MI A) ->
    0 <= n /\ 0 < p /\ p + n <= alloc_ceiling /\ (forall a, p <= a < p + n -> ~ owned MI A a /\ M (Z_to_bv 64 a) <> None).
Proof using AC L MI.
