    Theorem mva_correct : srealizes SEGS (cfg fx R0 MVA M0 model0) K.
Proof using AC L MI ST DEL_STACK DEL_STACK_nn DEL HLdel HLimg_lo HLrw_img HLrelro_img HLrw_relro HLerr_rw NS V nval HNS nval_agree fx A0 s R0 M0 model0 sp ret obj1 bl1 bc1 obj2 bl2 bc2 ents1 ents2 K CB H10 H11 U1 U2 AS1 AS2 AP12 DJ CONT.
Ltac nrwC Hj := nadd; repeat match goal with |- context [?x + -1] => change (x + -1) with (x - 1) end;
                        rewrite ?w_and, ?w_remu by lia; rewrite ?w_mul by lia; nadd; rewrite ?v_addi_Z by lia; rewrite ?Z.add_0_r; rewrite ?Hj.
Ltac scC Hland Hj Hdef2 Hdef5 idx :=
          split_scs;
          lazymatch goal with
          | |- sc_denot _ _ _ (SCStoreOk _ _) =>
              first [ sc_so; apply Hdef2; lia
                    | eapply (sc_storeok _ _ _ _ (bl2 + 8 * idx) 8); [evs; nrwC Hj; first [reflexivity | f_equal; lia] | lia | cbn [a_off]; lia | cbn [a_off]; lia | cbn [a_off]; exact Hdef5] ]
          | |- sc_denot _ _ _ (SCFlat _ _) =>
              first [ sc_fl | eapply (sc_flat _ _ _ _ (bl2 + 8 * idx)); [evs; nrwC Hj; first [reflexivity | f_equal; lia] | lia | cbn [a_off]; lia | lia | cbn [a_off]; lia] ]
          | |- sc_denot _ _ _ (SCBr false BC_NE (EAlu ALU_AND _ (ELit 7)) (ELit 0)) =>
              eapply sc_trap_align; [evs; nrwC Hj; reflexivity | lia
                                    | first [assumption | apply align16_8; assumption | apply align8_add; apply align16_8; assumption
                                            | rewrite Z.add_comm; apply align8_add; apply align16_8; assumption] ]
          | |- sc_denot _ _ _ (SCBr false BC_NE (EAlu ALU_SRL _ (ELit 61)) (ELit 0)) => eapply sc_trap_srl; [evs; nrwC Hj; reflexivity | lia | lia]
          | |- sc_denot _ _ _ (SCBr false BC_EQ (EAlu ALU_SLTU (ELit 0) _) (EAlu ALU_SLTU _ (ELit 1))) =>
              eapply (sc_trap_nulleq _ _ _ _ _ (8 * _)); [evs; reflexivity | evs; nrwC Hj; first [reflexivity | rewrite Z.add_comm; reflexivity] | lia | lia | lia]
          | |- sc_denot _ _ _ (SCBr false BC_LTU (EAlu ALU_ADD _ _) (EVar _)) =>
              eapply (sc_trap_wrap _ _ _ _ _ _ (8 * _)); [evs; nrwC Hj; first [reflexivity | rewrite Z.add_comm; reflexivity] | evs; reflexivity | lia | lia | lia]
          | |- sc_denot _ _ _ (SCBr _ _ _ _) => cbn [sc_denot]; evs; nrwC Hj; rewrite ?Hland; rewrite ?br_ne, ?br_eq, ?br_ltu, ?br_geu by lia; bool_lia
          | |- _ => sc_auto1
